const IMGBB_API_KEY = "b8c205b3a397fdf1cd2b547a0731e074";

export const uploadToImgBB = async (file: File): Promise<string> => {
  const formData = new FormData();
  formData.append('image', file);

  try {
    const response = await fetch(`https://api.imgbb.com/1/upload?key=${IMGBB_API_KEY}`, {
      method: 'POST',
      body: formData,
    });
    const data = await response.json();
    if (data.success) {
      return data.data.url;
    } else {
      throw new Error(data.error?.message || 'Upload failed');
    }
  } catch (error) {
    console.error('ImgBB upload error:', error);
    throw error;
  }
};

import { 
  collection, 
  doc, 
  getDocs, 
  getDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy,
  limit,
  Timestamp,
  serverTimestamp
} from 'firebase/firestore';
import { db } from '../firebase';
import { Company, Customer, Invoice } from '../types';

// Company Services
export const getCompanyByOwner = async (uid: string): Promise<Company | null> => {
  const q = query(collection(db, 'companies'), where('ownerUid', '==', uid), limit(1));
  const snapshot = await getDocs(q);
  if (snapshot.empty) return null;
  const data = snapshot.docs[0].data();
  return { id: snapshot.docs[0].id, ...data } as Company;
};

export const createCompany = async (company: Company) => {
  return await addDoc(collection(db, 'companies'), company);
};

// Customer Services
export const getCustomers = async (uid: string): Promise<Customer[]> => {
  const q = query(collection(db, 'customers'), where('ownerUid', '==', uid));
  const snapshot = await getDocs(q);
  return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as Customer[];
};

export const createCustomer = async (customer: Customer) => {
  return await addDoc(collection(db, 'customers'), customer);
};

// Invoice Services
export const getInvoices = async (uid: string): Promise<Invoice[]> => {
  const q = query(
    collection(db, 'invoices'), 
    where('ownerUid', '==', uid),
    orderBy('createdAt', 'desc')
  );
  const snapshot = await getDocs(q);
  return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as Invoice[];
};

export const createInvoice = async (invoice: Omit<Invoice, 'id'>) => {
  return await addDoc(collection(db, 'invoices'), {
    ...invoice,
    createdAt: serverTimestamp()
  });
};

export const getLatestInvoiceNumber = async (uid: string): Promise<number> => {
  const q = query(
    collection(db, 'invoices'),
    where('ownerUid', '==', uid),
    orderBy('invoiceNumber', 'desc'),
    limit(1)
  );
  const snapshot = await getDocs(q);
  if (snapshot.empty) return 1000;
  const num = parseInt(snapshot.docs[0].data().invoiceNumber);
  return isNaN(num) ? 1000 : num + 1;
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { HashRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { auth } from './firebase';
import { getCompanyByOwner } from './services/database';
import { Company, UserContextType } from './types';

// Pages
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import CompanySetup from './pages/CompanySetup';
import InvoiceList from './pages/InvoiceList';
import CreateInvoice from './pages/CreateInvoice';
import CustomerList from './pages/CustomerList';

// Layout
import SidebarLayout from './components/SidebarLayout';

const UserContext = createContext<UserContextType>({
  user: null,
  company: null,
  loading: true,
  refreshCompany: async () => {},
});

export const useUser = () => useContext(UserContext);

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [company, setCompany] = useState<Company | null>(null);
  const [loading, setLoading] = useState(true);

  const refreshCompany = async (uid?: string) => {
    const userId = uid || user?.uid;
    if (userId) {
      const companyData = await getCompanyByOwner(userId);
      setCompany(companyData);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        await refreshCompany(currentUser.uid);
      } else {
        setCompany(null);
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, [user?.uid]);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <UserContext.Provider value={{ user, company, loading, refreshCompany }}>
      <HashRouter>
        <Routes>
          <Route path="/login" element={!user ? <Login /> : <Navigate to="/" />} />

          <Route element={<ProtectedRoute />}>
            <Route path="/setup" element={company ? <Navigate to="/" /> : <CompanySetup />} />

            <Route element={<CompanyRequiredRoute />}>
              <Route element={<SidebarLayout />}>
                <Route path="/" element={<Dashboard />} />
                <Route path="/invoices" element={<InvoiceList />} />
                <Route path="/invoices/new" element={<CreateInvoice />} />
                <Route path="/customers" element={<CustomerList />} />
              </Route>
            </Route>
          </Route>

          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </HashRouter>
    </UserContext.Provider>
  );
};

const ProtectedRoute = () => {
  const { user } = useUser();
  return user ? <Routes><Route path="*" element={<OutletWrapper />} /></Routes> : <Navigate to="/login" />;
};

const CompanyRequiredRoute = () => {
  const { company } = useUser();
  return company ? <Routes><Route path="*" element={<OutletWrapper />} /></Routes> : <Navigate to="/setup" />;
};

// Workaround for direct route rendering inside ProtectedRoutes
import { Outlet } from 'react-router-dom';
const OutletWrapper = () => <Outlet />;

export default App;

