import React, { useEffect, useState } from 'react';
import { useUser } from '../App';
import { getInvoices, getCustomers } from '../services/database';
import { Invoice, Customer } from '../types';
import { 
  TrendingUp, 
  Users, 
  FileText, 
  Clock, 
  ArrowRight,
  PlusCircle
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const Dashboard: React.FC = () => {
  const { user } = useUser();
  const navigate = useNavigate();
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      if (user) {
        const [invData, custData] = await Promise.all([
          getInvoices(user.uid),
          getCustomers(user.uid)
        ]);
        setInvoices(invData);
        setCustomers(custData);
      }
      setLoading(false);
    };
    loadData();
  }, [user]);

  const totalSales = invoices.reduce((sum, inv) => sum + inv.grandTotal, 0);
  const pendingInvoices = invoices.length; // Simplified for this view

  if (loading) return <div className="animate-pulse space-y-8">
    <div className="h-32 bg-slate-200 rounded-2xl w-full"></div>
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
      <div className="h-40 bg-slate-200 rounded-2xl"></div>
      <div className="h-40 bg-slate-200 rounded-2xl"></div>
      <div className="h-40 bg-slate-200 rounded-2xl"></div>
    </div>
  </div>;

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Dashboard</h1>
          <p className="text-slate-500">Welcome back! Here's what's happening today.</p>
        </div>
        <button 
          onClick={() => navigate('/invoices/new')}
          className="bg-primary text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-primary/90 shadow-lg shadow-primary/25 transform hover:-translate-y-0.5 transition-all"
        >
          <PlusCircle size={20} />
          Create Invoice
        </button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total Revenue" 
          value={`$${totalSales.toLocaleString()}`} 
          icon={<TrendingUp className="text-green-600" />}
          color="bg-green-100"
        />
        <StatCard 
          title="Total Invoices" 
          value={invoices.length.toString()} 
          icon={<FileText className="text-primary" />}
          color="bg-blue-100"
        />
        <StatCard 
          title="Total Customers" 
          value={customers.length.toString()} 
          icon={<Users className="text-purple-600" />}
          color="bg-purple-100"
        />
        <StatCard 
          title="Pending Payments" 
          value={pendingInvoices.toString()} 
          icon={<Clock className="text-orange-600" />}
          color="bg-orange-100"
        />
      </div>

      {/* Recent Invoices Table */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
          <h2 className="text-lg font-bold text-slate-800">Recent Invoices</h2>
          <button 
            onClick={() => navigate('/invoices')}
            className="text-primary font-medium text-sm flex items-center gap-1 hover:underline"
          >
            View all <ArrowRight size={16} />
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-500 text-xs uppercase tracking-wider font-semibold">
                <th className="px-6 py-4">Invoice #</th>
                <th className="px-6 py-4">Customer</th>
                <th className="px-6 py-4">Date</th>
                <th className="px-6 py-4">Amount</th>
                <th className="px-6 py-4">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.slice(0, 5).map((invoice) => (
                <tr key={invoice.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 font-medium text-slate-800">#{invoice.invoiceNumber}</td>
                  <td className="px-6 py-4 text-slate-600">
                    {customers.find(c => c.id === invoice.customerId)?.customerName || 'Unknown'}
                  </td>
                  <td className="px-6 py-4 text-slate-600">
                    {invoice.invoiceDate.toDate().toLocaleDateString()}
                  </td>
                  <td className="px-6 py-4 font-bold text-slate-800">${invoice.grandTotal.toFixed(2)}</td>
                  <td className="px-6 py-4">
                    <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full text-xs font-bold">
