import React, { useState, useEffect } from 'react';
import { useUser } from '../App';
import { getCustomers, getLatestInvoiceNumber, createInvoice, createCustomer } from '../services/database';
import { Customer, InvoiceItem } from '../types';
import { Timestamp } from 'firebase/firestore';
import { useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Calendar, 
  UserPlus, 
  FileCheck, 
  Calculator,
  ChevronLeft
} from 'lucide-react';

const CreateInvoice: React.FC = () => {
  const { user, company } = useUser();
  const navigate = useNavigate();

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  const [invoiceNumber, setInvoiceNumber] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [isAddingNewCustomer, setIsAddingNewCustomer] = useState(false);
  const [newCustomer, setNewCustomer] = useState({
    customerName: '',
    customerEmail: '',
    customerPhone: '',
    customerAddress: ''
  });

  const [items, setItems] = useState<InvoiceItem[]>([
    { name: '', quantity: 1, price: 0, total: 0 }
  ]);
  const [discountPercent, setDiscountPercent] = useState(0);
  const [taxPercent, setTaxPercent] = useState(0);
  const [invoiceDate, setInvoiceDate] = useState(new Date().toISOString().split('T')[0]);
  const [dueDate, setDueDate] = useState(new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]);

  useEffect(() => {
    const fetchData = async () => {
      if (user) {
        const [custData, latestNum] = await Promise.all([
          getCustomers(user.uid),
          getLatestInvoiceNumber(user.uid)
        ]);
        setCustomers(custData);
        setInvoiceNumber(latestNum.toString());
      }
      setLoading(false);
    };
    fetchData();
  }, [user]);

  const handleItemChange = (index: number, field: keyof InvoiceItem, value: any) => {
    const newItems = [...items];
    const item = { ...newItems[index], [field]: value };

    if (field === 'quantity' || field === 'price') {
      item.total = item.quantity * item.price;
    }

    newItems[index] = item;
    setItems(newItems);
  };

  const addItem = () => {
    setItems([...items, { name: '', quantity: 1, price: 0, total: 0 }]);
  };

  const removeItem = (index: number) => {
    if (items.length > 1) {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const calculateSubtotal = () => items.reduce((sum, item) => sum + item.total, 0);
  const subtotal = calculateSubtotal();
  const discountAmount = subtotal * (discountPercent / 100);
  const taxAmount = (subtotal - discountAmount) * (taxPercent / 100);
  const grandTotal = subtotal - discountAmount + taxAmount;

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setSubmitting(true);

    try {
      let finalCustomerId = selectedCustomerId;

      if (isAddingNewCustomer) {
        const custRef = await createCustomer({ ...newCustomer, ownerUid: user.uid });
        finalCustomerId = custRef.id;
      }

      if (!finalCustomerId) {
        throw new Error("Please select or create a customer");
      }

      await createInvoice({
        invoiceNumber,
        customerId: finalCustomerId,
        items,
        subTotal: subtotal,
        discount: discountPercent,
        tax: taxPercent,
        grandTotal: grandTotal,
        invoiceDate: Timestamp.fromDate(new Date(invoiceDate)),
        dueDate: Timestamp.fromDate(new Date(dueDate)),
        createdAt: Timestamp.now(),
        ownerUid: user.uid
      });

      navigate('/invoices');
    } catch (err: any) {
      alert(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div className="animate-pulse">Loading...</div>;

  return (
    <div className="max-w-5xl mx-auto pb-20">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => navigate(-1)} className="p-2 hover:bg-white rounded-full transition-colors">
          <ChevronLeft size={24} />
        </button>
        <div>
          <h1 className="text-2xl font-bold text-slate-800">Create New Invoice</h1>
          <p className="text-slate-500 text-sm">Fill in the details below to generate an invoice.</p>
        </div>
      </div>

      <form onSubmit={handleSave} className="space-y-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Left Column - Invoice Basics */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 space-y-6">
              <div className="flex items-center gap-2 text-primary font-bold mb-4">
                <UserPlus size={20} />
                <span>Customer Information</span>
              </div>

              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={() => setIsAddingNewCustomer(false)}
                  className={`flex-1 py-2 rounded-lg text-sm font-bold border ${!isAddingNewCustomer ? 'bg-primary text-white border-primary' : 'bg-transparent text-slate-400 border-slate-200'}`}
                >
                  Existing Customer
                </button>
                <button
                  type="button"
                  onClick={() => setIsAddingNewCustomer(true)}
                  className={`flex-1 py-2 rounded-lg text-sm font-bold border ${isAddingNewCustomer ? 'bg-primary text-white border-primary' : 'bg-transparent text-slate-400 border-slate-200'}`}
                >
                  New Customer
                </button>
              </div>

              {!isAddingNewCustomer ? (
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Select Customer</label>
                  <select
                    className="input-primary"
                    value={selectedCustomerId}
                    onChange={(e) => setSelectedCustomerId(e.target.value)}
                    required={!isAddingNewCustomer}
                  >
                    <option value="">Choose a customer...</option>
                    {customers.map((c) => (
                      <option key={c.id} value={c.id}>{c.customerName}</option>
                    ))}
                  </select>
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <input
                    placeholder="Customer Name"
                    className="input-primary"
                    value={newCustomer.customerName}
                    onChange={(e) => setNewCustomer({...newCustomer, customerName: e.target.value})}
                    required
                  />
                  <input
                    placeholder="Email Address"
                    className="input-primary"
                    value={newCustomer.customerEmail}
                    onChange={(e) => setNewCustomer({...newCustomer, customerEmail: e.target.value})}
                    required
                  />
                  <input
                    placeholder="Phone"
                    className="input-primary"
                    value={newCustomer.customerPhone}
                    onChange={(e) => setNewCustomer({...newCustomer, customerPhone: e.target.value})}
                  />
                  <input
                    placeholder="Address"
                    className="input-primary"
                    value={newCustomer.customerAddress}
                    onChange={(e) => setNewCustomer({...newCustomer, customerAddress: e.target.value})}
                  />
                </div>
              )}
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-2 text-primary font-bold">
                  <FileCheck size={20} />
                  <span>Invoice Items</span>
                </div>
                <button
                  type="button"
                  onClick={addItem}
                  className="bg-slate-50 text-primary p-2 rounded-lg hover:bg-primary hover:text-white transition-all"
                >
                  <Plus size={20} />
                </button>
              </div>

              <div className="space-y-4">
                {items.map((item, index) => (
                  <div key={index} className="grid grid-cols-12 gap-3 items-end border-b border-slate-50 pb-4">
                    <div className="col-span-5">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Item Description</label>
                      <input
                        placeholder="e.g. Graphic Design"
                        className="input-primary text-sm py-2"
                        value={item.name}
                        onChange={(e) => handleItemChange(index, 'name', e.target.value)}
                        required
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Qty</label>
                      <input
                        type="number"
                        className="input-primary text-sm py-2 text-center"
                        value={item.quantity}
                        onChange={(e) => handleItemChange(index, 'quantity', parseInt(e.target.value) || 0)}
                        required
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Price</label>
                      <input
                        type="number"
                        className="input-primary text-sm py-2"
                        value={item.price}
                        onChange={(e) => handleItemChange(index, 'price', parseFloat(e.target.value) || 0)}
                        required
                      />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Total</label>
                      <div className="px-2 py-2 text-sm font-bold text-slate-700 bg-slate-50 rounded-lg text-right">
                        ${item.total.toFixed(2)}
                      </div>
                    </div>
                    <div className="col-span-1 pb-1">
                      <button
                        type="button"
                        onClick={() => removeItem(index)}
                        className="text-red-400 hover:text-red-600 transition-colors p-2"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Right Column - Summary & Dates */}
          <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 space-y-4">
              <div className="flex items-center gap-2 text-primary font-bold mb-2">
                <Calendar size={20} />
                <span>Dates & Numbers</span>
              </div>

              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Invoice #</label>
                <input
                  className="input-primary bg-slate-50"
                  value={invoiceNumber}
                  onChange={(e) => setInvoiceNumber(e.target.value)}
                  required
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Invoice Date</label>
                <input
                  type="date"
                  className="input-primary"
                  value={invoiceDate}
                  onChange={(e) => setInvoiceDate(e.target.value)}
                  required
                />
              </div>

              <div>
                <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1">Due Date</label>
                <input
                  type="date"
                  className="input-primary"
                  value={dueDate}
                  onChange={(e) => setDueDate(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="bg-primary text-white p-6 rounded-2xl shadow-lg shadow-primary/20 space-y-4">
              <div className="flex items-center gap-2 font-bold mb-4">
                <Calculator size={20} />
                <span>Financial Summary</span>
              </div>

              <div className="space-y-3 text-sm border-b border-white/20 pb-4">
                <div className="flex justify-between">
                  <span>Subtotal</span>
                  <span className="font-bold">${subtotal.toFixed(2)}</span>
                </div>

                <div className="flex flex-col gap-2">
                  <div className="flex justify-between items-center">
                    <span>Discount ({discountPercent}%)</span>
                    <span className="font-bold">-${discountAmount.toFixed(2)}</span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
                    value={discountPercent}
                    onChange={(e) => setDiscountPercent(parseInt(e.target.value))}
                    className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-white"
                  />
                </div>

                <div className="flex flex-col gap-2">
                  <div className="flex justify-between items-center">
                    <span>Tax ({taxPercent}%)</span>
                    <span className="font-bold">+${taxAmount.toFixed(2)}</span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="30"
                    value={taxPercent}
                    onChange={(e) => setTaxPercent(parseInt(e.target.value))}
                    className="w-full h-1 bg-white/20 rounded-lg appearance-none cursor-pointer accent-white"
                  />
                </div>
              </div>

              <div className="pt-2">
                <div className="flex justify-between items-center">
                  <span className="text-lg font-medium opacity-80">Grand Total</span>
                  <span className="text-2xl font-black">${grandTotal.toFixed(2)}</span>
                </div>
              </div>

              <button
                type="submit"
                disabled={submitting}
                className="w-full bg-white text-primary py-4 rounded-xl font-bold mt-4 hover:bg-slate-50 transition-all flex items-center justify-center gap-2"
              >
                {submitting ? (
                  <div className="w-6 h-6 border-2 border-primary/30 border-t-primary rounded-full animate-spin"></div>
                ) : (
                  <>Generate Invoice</>
                )}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

