import { Timestamp } from 'firebase/firestore';

export interface Company {
  id?: string;
  name: string;
  email: string;
  phone: string;
  address: string;
  photo: string;
  templateId?: 'standard' | 'minimal' | 'modern' | 'classic';
  currency?: string;
  paymentMethods?: string[];
}

export interface Customer {
  id?: string;
  name: string;
  email: string;
  phone: string;
  address: string;
}

export interface InvoiceItem {
  name: string;
  quantity: number;
  price: number;
  total: number;
}

export interface Invoice {
  id?: string; // Firestore Doc ID
  invoiceId: string; // Model ID
  invoiceNo: string;
  customerId: string;
  customerName: string;
  status: string;
  date: Timestamp;
  time: string;
  paymentSystem: string;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  items: InvoiceItem[];
}

export interface UserContextType {
  user: any;
  company: Company | null;
  loading: boolean;
  refreshCompany: (uid?: string) => Promise<void>;
}

import { 
  collection, 
  doc, 
  getDocs, 
  getDoc, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy,
  limit,
  Timestamp,
  serverTimestamp,
  writeBatch
} from 'firebase/firestore';
import { db } from '../firebase';
import { Company, Customer, Invoice } from '../types';

// Company Services
export const getCompanyByOwner = async (uid: string): Promise<Company | null> => {
  const q = query(collection(db, 'users', uid, 'companies'), limit(1));
  const snapshot = await getDocs(q);
  if (snapshot.empty) return null;
  const data = snapshot.docs[0].data();
  return { id: snapshot.docs[0].id, ...data } as Company;
};

export const createCompany = async (company: Company & { ownerUid: string }) => {
  const { ownerUid, ...companyData } = company;
  return await addDoc(collection(db, 'users', ownerUid, 'companies'), companyData);
};

export const updateCompany = async (uid: string, companyId: string, data: Partial<Company>) => {
  const docRef = doc(db, 'users', uid, 'companies', companyId);
  return await updateDoc(docRef, data);
};

// Customer Services
export const getCustomers = async (uid: string): Promise<Customer[]> => {
  const q = query(collection(db, 'users', uid, 'customers'));
  const snapshot = await getDocs(q);
  return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as Customer[];
};

export const createCustomer = async (customer: Customer & { ownerUid: string }) => {
  const { ownerUid, ...customerData } = customer;
  return await addDoc(collection(db, 'users', ownerUid, 'customers'), customerData);
};

export const updateCustomer = async (uid: string, customerId: string, data: Partial<Customer>) => {
  const docRef = doc(db, 'users', uid, 'customers', customerId);
  return await updateDoc(docRef, data);
};

export const deleteCustomer = async (uid: string, customerId: string) => {
  // Cascading delete: First delete all invoices for this customer
  const invoicesRef = collection(db, 'users', uid, 'customers', customerId, 'invoices');
  const invoicesSnapshot = await getDocs(invoicesRef);

  const batch = writeBatch(db);
  invoicesSnapshot.docs.forEach((doc) => {
    batch.delete(doc.ref);
  });

  // Delete the customer document
  const customerRef = doc(db, 'users', uid, 'customers', customerId);
  batch.delete(customerRef);

  await batch.commit();
};

// Invoice Services
export const getInvoices = async (uid: string): Promise<Invoice[]> => {
  const customers = await getCustomers(uid);

  const invoicePromises = customers.map(async (customer) => {
    if (!customer.id) return [];
    const q = query(
      collection(db, 'users', uid, 'customers', customer.id, 'invoices')
    );
    const snapshot = await getDocs(q);
    return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Invoice));
  });

  const results = await Promise.all(invoicePromises);
  const allInvoices = results.flat();

  return allInvoices.sort((a, b) => {
    const timeA = a.date?.toMillis ? a.date.toMillis() : 0;
    const timeB = b.date?.toMillis ? b.date.toMillis() : 0;
    return timeB - timeA;
  });
};

export const getInvoiceById = async (uid: string, customerId: string, invoiceId: string): Promise<Invoice | null> => {
  const docRef = doc(db, 'users', uid, 'customers', customerId, 'invoices', invoiceId);
  const snapshot = await getDoc(docRef);
  if (!snapshot.exists()) return null;
  return { id: snapshot.id, ...snapshot.data() } as Invoice;
};

export const createInvoice = async (invoice: Omit<Invoice, 'id'>, uid: string) => {
  if (!invoice.customerId) {
    throw new Error("Cannot create invoice without a Customer ID");
  }
  return await addDoc(collection(db, 'users', uid, 'customers', invoice.customerId, 'invoices'), invoice);
};

export const deleteInvoice = async (uid: string, customerId: string, invoiceId: string) => {
  const docRef = doc(db, 'users', uid, 'customers', customerId, 'invoices', invoiceId);
  return await deleteDoc(docRef);
};

export const getLatestInvoiceNumber = async (uid: string): Promise<number> => {
  const invoices = await getInvoices(uid);
  if (invoices.length === 0) return 1000;

  const max = invoices.reduce((prev, current) => {
    const currentNo = parseInt(current.invoiceNo);
    const validNo = isNaN(currentNo) ? 0 : currentNo;
    return validNo > prev ? validNo : prev;
  }, 0);

  return max === 0 ? 1000 : max + 1;
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { auth } from './firebase';
import { getCompanyByOwner } from './services/database';
import { Company, UserContextType } from './types';
import { ToastProvider } from './context/ToastContext';

// Pages
import Landing from './pages/Landing';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import CompanySetup from './pages/CompanySetup';
import InvoiceList from './pages/InvoiceList';
import CreateInvoice from './pages/CreateInvoice';
import InvoiceDetails from './pages/InvoiceDetails';
import CustomerList from './pages/CustomerList';
import Settings from './pages/Settings';

// Layout
import SidebarLayout from './components/SidebarLayout';

const UserContext = createContext<UserContextType>({
  user: null,
  company: null,
  loading: true,
  refreshCompany: async () => {},
});

export const useUser = () => useContext(UserContext);

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [company, setCompany] = useState<Company | null>(null);
  const [loading, setLoading] = useState(true);

  // Load theme preference
  useEffect(() => {
    const applyTheme = () => {
      const savedTheme = localStorage.getItem('theme') || 'system';
      const root = document.documentElement;

      if (savedTheme === 'dark') {
        root.classList.add('dark');
      } else if (savedTheme === 'light') {
        root.classList.remove('dark');
      } else {
        // System preference
        if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
          root.classList.add('dark');
        } else {
          root.classList.remove('dark');
        }
      }
    };

    applyTheme();

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handleSystemChange = () => applyTheme();

    mediaQuery.addEventListener('change', handleSystemChange);
    return () => mediaQuery.removeEventListener('change', handleSystemChange);
  }, []);

  const refreshCompany = async (uid?: string) => {
    const userId = uid || user?.uid;
    if (userId) {
      const companyData = await getCompanyByOwner(userId);
      setCompany(companyData);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        await refreshCompany(currentUser.uid);
      } else {
        setCompany(null);
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, [user?.uid]);

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50 dark:bg-slate-900">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <ToastProvider>
      <UserContext.Provider value={{ user, company, loading, refreshCompany }}>
        <BrowserRouter>
          <Routes>
            <Route path="/" element={<Landing />} />
            <Route path="/login" element={!user ? <Login /> : <Navigate to="/dashboard" />} />

            <Route element={<ProtectedRoute />}>
              <Route path="/setup" element={<CompanySetup />} />

              <Route element={<CompanyRequiredRoute />}>
                <Route element={<SidebarLayout />}>
                  <Route path="/dashboard" element={<Dashboard />} />
                  <Route path="/invoices" element={<InvoiceList />} />
                  <Route path="/invoices/new" element={<CreateInvoice />} />
                  <Route path="/invoices/:customerId/:invoiceId" element={<InvoiceDetails />} />
                  <Route path="/customers" element={<CustomerList />} />
                  <Route path="/settings" element={<Settings />} />
                </Route>
              </Route>
            </Route>

            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </BrowserRouter>
      </UserContext.Provider>
    </ToastProvider>
  );
};

const ProtectedRoute = () => {
  const { user } = useUser();
  return user ? <Outlet /> : <Navigate to="/login" />;
};

const CompanyRequiredRoute = () => {
  const { company } = useUser();
  // Check if we are already on the setup page to avoid infinite redirect loop
  const isSetupPage = window.location.pathname === '/setup';
  return company ? <Outlet /> : (isSetupPage ? <Outlet /> : <Navigate to="/setup" />);
};

export default App;

import React, { useState, useEffect } from 'react';
import { useUser } from '../App';
import { createCompany, updateCompany } from '../services/database';
import { uploadToImgBB } from '../services/imgbb';
import { useNavigate } from 'react-router-dom';
import { Building2, Mail, Phone, MapPin, Upload, ChevronRight, PlusCircle, ArrowLeft } from 'lucide-react';
import { useToast } from '../context/ToastContext';

const CompanySetup: React.FC = () => {
  const { user, company, refreshCompany } = useUser();
  const navigate = useNavigate();
  const { success, error } = useToast();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
  });
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);

  // Pre-fill data if company exists (Edit Mode)
  useEffect(() => {
    if (company) {
      setFormData({
        name: company.name,
        email: company.email,
        phone: company.phone,
        address: company.address,
      });
      if (company.photo) {
        setLogoPreview(company.photo);
      }
    }
  }, [company]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setLogoFile(file);
      setLogoPreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setLoading(true);

    try {
      let photo = company?.photo || '';
      if (logoFile) {
        photo = await uploadToImgBB(logoFile);
      }

      if (company?.id) {
        // Update existing
        await updateCompany(user.uid, company.id, {
          ...formData,
          photo,
        });
        success('Company profile updated!');
        navigate('/settings');
      } else {
        // Create new
        await createCompany({
          ...formData,
          photo,
          ownerUid: user.uid,
          currency: '$',
          paymentMethods: ['Cash', 'Card', 'Bank Transfer'],
          templateId: 'standard'
        });
        success('Welcome! Company profile setup complete.');
        navigate('/dashboard');
      }

      await refreshCompany();
    } catch (err) {
      console.error(err);
      error('Failed to save company profile.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center p-6">
