import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './hooks/useAuth';
import Landing from './pages/Landing';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import CompanySetup from './pages/CompanySetup';
import { CompanyRequiredRoute } from './components/CompanyRequiredRoute';
import { ProtectedRoute } from './components/ProtectedRoute';
import { Logo } from './components/Logo'; // Import the Logo component

function RootRoute() {
  const { user, loading, company, refreshCompany } = useAuth();
  const [redirectPath, setRedirectPath] = useState<string | null>(null);

  useEffect(() => {
    const checkRedirection = async () => {
      if (loading) {
        return; // Wait for auth loading
      }

      if (!user) {
        setRedirectPath('/');
      } else if (!company) {
        setRedirectPath('/company-setup');
      } else {
        setRedirectPath('/dashboard');
      }
    };
    checkRedirection();
  }, [user, loading, company, refreshCompany]);


  if (redirectPath === null) {
    return <p>Loading...</p>;
  }

  return <Navigate to={redirectPath} replace />;
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<RootRoute />} />
        <Route path="/login" element={<Login />} />
        <Route path="/company-setup" element={<ProtectedRoute><CompanySetup /></ProtectedRoute>} />
        <Route path="/dashboard" element={<CompanyRequiredRoute><Dashboard /></CompanyRequiredRoute>} />
      </Routes>
    </Router>
  );
}

export default App;
