                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800 dark:text-white">#{invoice.invoiceNo}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-800 dark:text-white">{invoice.customerName}</div>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-600 dark:text-slate-300">
                      {invoice.date?.toDate ? invoice.date.toDate().toLocaleDateString() : 'N/A'}
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800 dark:text-white">${invoice.total.toFixed(2)}</div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                        invoice.status === 'Paid' ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' : 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
                      }`}>
                        {invoice.status}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button className="p-2 text-slate-400 hover:text-primary transition-colors" title="View">
                          <Eye size={18} />
                        </button>
                        <button 
                            className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                            onClick={(e) => handleDelete(e, invoice)}
                            title="Delete"
                        >
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredInvoices.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-6 py-20 text-center text-slate-400">
                    <div className="flex flex-col items-center gap-2">
                      <FileText size={48} className="opacity-20 mb-2" />
                      <p>No invoices found matching your search.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default InvoiceList;

import React, { useEffect, useState } from 'react';
import { useUser } from '../App';
import { getCustomers, createCustomer, updateCustomer, deleteCustomer } from '../services/database';
import { Customer } from '../types';
import { 
  Users, 
  Mail, 
  Phone, 
  MapPin, 
  Search,
  PlusCircle,
  Trash2,
  Edit2
} from 'lucide-react';
import { useToast } from '../context/ToastContext';
import { Loader } from '../components/Loader';

const CustomerList: React.FC = () => {
  const { user } = useUser();
  const { success, error, info } = useToast();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');

  // Modal State
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [currentId, setCurrentId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: ''
  });

  const loadCustomers = async () => {
    if (user) {
      const data = await getCustomers(user.uid);
      setCustomers(data);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadCustomers();
  }, [user]);

  const openAddModal = () => {
    setFormData({ name: '', email: '', phone: '', address: '' });
    setIsEditing(false);
    setShowModal(true);
  };

  const openEditModal = (customer: Customer) => {
    setFormData({
        name: customer.name,
        email: customer.email,
        phone: customer.phone,
        address: customer.address
    });
    setCurrentId(customer.id!);
    setIsEditing(true);
    setShowModal(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setLoading(true);
    try {
      if (isEditing && currentId) {
        await updateCustomer(user.uid, currentId, formData);
        success('Customer updated successfully');
      } else {
        await createCustomer({ ...formData, ownerUid: user.uid });
        success('Customer created successfully');
      }
      setShowModal(false);
      await loadCustomers();
    } catch (err) {
      error('Operation failed');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (customerId: string) => {
    if (!user) return;
    if (confirm('Are you sure? This will delete the customer.')) {
        await deleteCustomer(user.uid, customerId);
        info('Customer deleted');
        await loadCustomers();
    }
  };

  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading && customers.length === 0) return <Loader fullScreen={false} />;

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 dark:text-white">Customers</h1>
          <p className="text-slate-500 dark:text-slate-400">Manage your business contacts and client relationships.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-primary text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-primary/90 shadow-lg shadow-primary/25 transition-all"
        >
          <PlusCircle size={20} />
          Add Customer
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
        <input
          type="text"
          placeholder="Search by name or email..."
          className="input-primary pl-12 dark:bg-slate-800 dark:border-slate-700"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredCustomers.map((customer) => (
          <div key={customer.id} className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 hover:border-primary/30 transition-all group relative">

            {/* Actions */}
            <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => openEditModal(customer)}
                  className="p-2 bg-slate-100 dark:bg-slate-700 rounded-full hover:bg-primary hover:text-white transition-colors">
                    <Edit2 size={16} />
                </button>
                <button 
                  onClick={() => handleDelete(customer.id!)}
                  className="p-2 bg-red-50 dark:bg-slate-700 text-red-500 rounded-full hover:bg-red-500 hover:text-white transition-colors">
                    <Trash2 size={16} />
                </button>
            </div>

            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 bg-accent dark:bg-slate-700 rounded-xl flex items-center justify-center text-primary text-xl font-bold">
                {customer.name.charAt(0)}
              </div>
            </div>

            <h3 className="font-bold text-lg text-slate-800 dark:text-white mb-1">{customer.name}</h3>
            <div className="space-y-2 mt-4">
              <div className="flex items-center gap-3 text-slate-500 dark:text-slate-400 text-sm">
                <Mail size={16} className="text-primary" />
                <span className="truncate">{customer.email}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500 dark:text-slate-400 text-sm">
                <Phone size={16} className="text-primary" />
                <span>{customer.phone || 'No phone'}</span>
              </div>
              <div className="flex items-center gap-3 text-slate-500 dark:text-slate-400 text-sm">
                <MapPin size={16} className="text-primary" />
                <span className="truncate">{customer.address || 'No address'}</span>
              </div>
            </div>
          </div>
        ))}

        {filteredCustomers.length === 0 && (
          <div className="col-span-full py-20 text-center text-slate-400 bg-white dark:bg-slate-800 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700">
            <Users size={48} className="mx-auto mb-4 opacity-20" />
            <p>No customers found.</p>
          </div>
        )}
      </div>

      {/* Add/Edit Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setShowModal(false)}></div>
          <div className="bg-white dark:bg-slate-800 w-full max-w-md rounded-3xl shadow-2xl relative z-10 overflow-hidden">
            <div className="bg-primary p-6 text-white">
              <h2 className="text-xl font-bold">{isEditing ? 'Edit Customer' : 'New Customer'}</h2>
              <p className="text-primary-foreground/70 text-sm">Enter client details below.</p>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <input
                required
                placeholder="Full Name"
                className="input-primary"
                value={formData.name}
                onChange={(e) => setFormData({...formData, name: e.target.value})}
              />
              <input
                required
                type="email"
                placeholder="Email Address"
                className="input-primary"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
              />
              <input
                placeholder="Phone Number"
                className="input-primary"
                value={formData.phone}
                onChange={(e) => setFormData({...formData, phone: e.target.value})}
              />
              <textarea
                placeholder="Address"
                className="input-primary h-24 resize-none"
                value={formData.address}
                onChange={(e) => setFormData({...formData, address: e.target.value})}
              />
              <div className="flex gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 py-3 bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-xl font-bold"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="flex-1 py-3 bg-primary text-white rounded-xl font-bold shadow-lg shadow-primary/20"
                >
                  Save Customer
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default CustomerList;

import React, { useState, useEffect } from 'react';
import { useUser } from '../App';
import { getCustomers, getLatestInvoiceNumber, createInvoice, createCustomer } from '../services/database';
import { Customer, InvoiceItem } from '../types';
import { Timestamp } from 'firebase/firestore';
import { useNavigate } from 'react-router-dom';
import { InvoicePreview } from '../components/InvoicePreview';
import { 
  Plus, 
  Trash2, 
  UserPlus, 
  ChevronLeft,
  Eye
} from 'lucide-react';
import { useToast } from '../context/ToastContext';
import { Loader } from '../components/Loader';

const CreateInvoice: React.FC = () => {
  const { user, company } = useUser();
  const navigate = useNavigate();
  const { success, error } = useToast();

  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [showMobilePreview, setShowMobilePreview] = useState(false);

  const [invoiceNo, setInvoiceNo] = useState('');
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [isAddingNewCustomer, setIsAddingNewCustomer] = useState(false);
  const [newCustomer, setNewCustomer] = useState({
    name: '',
    email: '',
    phone: '',
    address: ''
  });

  const [items, setItems] = useState<InvoiceItem[]>([
    { name: '', quantity: 1, price: 0, total: 0 }
  ]);
  const [discount, setDiscount] = useState(0);
  const [tax, setTax] = useState(0);
  const [invoiceDate, setInvoiceDate] = useState(new Date().toISOString().split('T')[0]);
  const [status, setStatus] = useState('Paid');
  const [paymentSystem, setPaymentSystem] = useState('Cash');

  // Derived customer name for preview
  const currentCustomerName = isAddingNewCustomer 
    ? newCustomer.name 
    : customers.find(c => c.id === selectedCustomerId)?.name || '';

  // Use configured payment methods or defaults
  const availablePaymentMethods = company?.paymentMethods && company.paymentMethods.length > 0 
    ? company.paymentMethods 
    : ['Cash', 'Card', 'Bank Transfer'];

  // Initialize paymentSystem with the first available option
  useEffect(() => {
    if (availablePaymentMethods.length > 0 && !availablePaymentMethods.includes(paymentSystem)) {
      setPaymentSystem(availablePaymentMethods[0]);
    }
  }, [availablePaymentMethods]);

  useEffect(() => {
    const fetchData = async () => {
      if (user) {
        const [custData, latestNum] = await Promise.all([
          getCustomers(user.uid),
          getLatestInvoiceNumber(user.uid)
        ]);
        setCustomers(custData);
        setInvoiceNo(latestNum.toString());
      }
      setLoading(false);
    };
    fetchData();
  }, [user]);

  const handleItemChange = (index: number, field: keyof InvoiceItem, value: any) => {
    const newItems = [...items];
    const item = { ...newItems[index], [field]: value };

    if (field === 'quantity' || field === 'price') {
      item.total = item.quantity * item.price;
    }

    newItems[index] = item;
    setItems(newItems);
  };

  const addItem = () => {
    setItems([...items, { name: '', quantity: 1, price: 0, total: 0 }]);
  };

  const removeItem = (index: number) => {
    if (items.length > 1) {
      setItems(items.filter((_, i) => i !== index));
    }
  };

  const calculateSubtotal = () => items.reduce((sum, item) => sum + item.total, 0);
  const subtotal = calculateSubtotal();
  const discountAmount = subtotal * (discount / 100);
  const taxAmount = (subtotal - discountAmount) * (tax / 100);
  const total = subtotal - discountAmount + taxAmount;

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setSubmitting(true);

    try {
      let finalCustomerId = selectedCustomerId;
      let finalCustomerName = '';

      if (isAddingNewCustomer) {
        const custRef = await createCustomer({ ...newCustomer, ownerUid: user.uid });
        finalCustomerId = custRef.id;
        finalCustomerName = newCustomer.name;
      } else {
        const existingCust = customers.find(c => c.id === selectedCustomerId);
        if (existingCust) finalCustomerName = existingCust.name;
      }

      if (!finalCustomerId) {
        throw new Error("Please select or create a customer");
      }

      const dateObj = new Date(invoiceDate);
      const timeString = dateObj.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      await createInvoice({
        invoiceId: '',
        invoiceNo,
        customerId: finalCustomerId,
        customerName: finalCustomerName,
        items,
        subtotal,
        discount,
        tax: taxAmount,
        status,
        date: Timestamp.fromDate(dateObj),
        time: timeString,
        paymentSystem,
        total,
      }, user.uid);

      success('Invoice created successfully!');
      navigate('/invoices');
    } catch (err: any) {
      error(err.message || 'Failed to create invoice');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <Loader fullScreen={false} />;

  return (
    <div className="h-[calc(100vh-80px)] overflow-hidden flex flex-col">
      <div className="flex items-center justify-between gap-4 mb-4 px-1 shrink-0">
        <div className="flex items-center gap-4">
            <button onClick={() => navigate(-1)} className="p-2 hover:bg-white rounded-full transition-colors">
            <ChevronLeft size={24} />
            </button>
            <div>
            <h1 className="text-2xl font-bold text-slate-800 dark:text-white">Create New Invoice</h1>
            </div>
        </div>
        <button 
          onClick={() => setShowMobilePreview(!showMobilePreview)}
          className="lg:hidden p-2 text-primary border border-primary rounded-lg"
        >
          <Eye size={20} />
        </button>
      </div>

      <div className="flex-1 flex gap-8 overflow-hidden">
        {/* Left Column - Input Form */}
        <div className={`flex-1 overflow-y-auto pb-20 lg:pb-0 ${showMobilePreview ? 'hidden lg:block' : 'block'}`}>
          <form onSubmit={handleSave} className="space-y-6 max-w-2xl">
            {/* Customer Section */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 space-y-6">
              <div className="flex items-center gap-2 text-primary font-bold mb-2">
                <UserPlus size={20} />
                <span>Customer Information</span>
              </div>

              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={() => setIsAddingNewCustomer(false)}
                  className={`flex-1 py-2 rounded-lg text-sm font-bold border ${!isAddingNewCustomer ? 'bg-primary text-white border-primary' : 'bg-transparent text-slate-400 border-slate-200'}`}
                >
                  Existing
                </button>
                <button
                  type="button"
                  onClick={() => setIsAddingNewCustomer(true)}
                  className={`flex-1 py-2 rounded-lg text-sm font-bold border ${isAddingNewCustomer ? 'bg-primary text-white border-primary' : 'bg-transparent text-slate-400 border-slate-200'}`}
                >
                  New
                </button>
              </div>

              {!isAddingNewCustomer ? (
                <select
                  className="input-primary dark:bg-slate-700"
                  value={selectedCustomerId}
                  onChange={(e) => setSelectedCustomerId(e.target.value)}
                  required={!isAddingNewCustomer}
                >
                  <option value="">Choose a customer...</option>
                  {customers.map((c) => (
                    <option key={c.id} value={c.id}>{c.name}</option>
                  ))}
                </select>
              ) : (
                <div className="grid grid-cols-1 gap-4">
                  <input
                    placeholder="Customer Name"
                    className="input-primary"
                    value={newCustomer.name}
                    onChange={(e) => setNewCustomer({...newCustomer, name: e.target.value})}
                    required
                  />
                  <div className="grid grid-cols-2 gap-4">
                    <input
                        placeholder="Email"
                        className="input-primary"
                        value={newCustomer.email}
                        onChange={(e) => setNewCustomer({...newCustomer, email: e.target.value})}
                        required
                    />
                    <input
                        placeholder="Phone"
                        className="input-primary"
                        value={newCustomer.phone}
                        onChange={(e) => setNewCustomer({...newCustomer, phone: e.target.value})}
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Invoice Details */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 grid grid-cols-2 gap-4">
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Invoice #</label>
                  <input className="input-primary" value={invoiceNo} onChange={(e) => setInvoiceNo(e.target.value)} required />
               </div>
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Date</label>
                  <input type="date" className="input-primary dark:text-slate-400" value={invoiceDate} onChange={(e) => setInvoiceDate(e.target.value)} required />
               </div>
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Status</label>
                  <select className="input-primary dark:bg-slate-700" value={status} onChange={(e) => setStatus(e.target.value)}>
                    <option value="Paid">Paid</option>
                    <option value="Unpaid">Unpaid</option>
                  </select>
               </div>
               <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Payment</label>
                  <select className="input-primary dark:bg-slate-700" value={paymentSystem} onChange={(e) => setPaymentSystem(e.target.value)}>
                    {availablePaymentMethods.map(method => (
                      <option key={method} value={method}>{method}</option>
                    ))}
                  </select>
               </div>
            </div>

            {/* Items */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
               <div className="flex justify-between items-center mb-4">
                  <h3 className="font-bold text-slate-700 dark:text-slate-300">Items</h3>
                  <button type="button" onClick={addItem} className="text-primary hover:bg-slate-50 dark:hover:bg-slate-700 p-2 rounded"><Plus size={18}/></button>
               </div>
               <div className="space-y-4">
                {items.map((item, index) => (
                  <div key={index} className="grid grid-cols-12 gap-2 items-end border-b border-slate-50 dark:border-slate-700 pb-2">
                    <div className="col-span-5">
                      <input placeholder="Item" className="input-primary text-sm py-2" value={item.name} onChange={(e) => handleItemChange(index, 'name', e.target.value)} required />
                    </div>
                    <div className="col-span-2">
                      <input type="number" className="input-primary text-sm py-2 px-1 text-center" value={item.quantity} onChange={(e) => handleItemChange(index, 'quantity', parseInt(e.target.value) || 0)} />
                    </div>
                    <div className="col-span-3">
                      <input type="number" className="input-primary text-sm py-2 px-1" value={item.price} onChange={(e) => handleItemChange(index, 'price', parseFloat(e.target.value) || 0)} />
                    </div>
                    <div className="col-span-2 flex items-center justify-between">
                       <span className="text-xs font-bold text-slate-600 dark:text-slate-400">${item.total.toFixed(0)}</span>
                       <button type="button" onClick={() => removeItem(index)} className="text-red-400 hover:text-red-600"><Trash2 size={16} /></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Totals Input */}
            <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 space-y-4">
                <div className="flex justify-between items-center dark:text-slate-300">
                    <span>Discount (%)</span>
