import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useUser } from '../App';
import { getInvoiceById, deleteInvoice } from '../services/database';
import { Invoice } from '../types';
import { InvoicePreview } from '../components/InvoicePreview';
import { ChevronLeft, Printer, Trash2 } from 'lucide-react';
import { Loader } from '../components/Loader';

const InvoiceDetails: React.FC = () => {
  const { invoiceId, customerId } = useParams();
  const { user, company } = useUser();
  const navigate = useNavigate();
  const [invoice, setInvoice] = useState<Invoice | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadInvoice = async () => {
      if (user && invoiceId && customerId) {
        const data = await getInvoiceById(user.uid, customerId, invoiceId);
        setInvoice(data);
      }
      setLoading(false);
    };
    loadInvoice();
  }, [user, invoiceId, customerId]);

  const handleDelete = async () => {
    if (!user || !invoice || !invoice.customerId) return;
    if (confirm('Are you sure you want to delete this invoice? This action cannot be undone.')) {
        await deleteInvoice(user.uid, invoice.customerId, invoice.id!);
        navigate('/invoices');
    }
  };

  const handlePrint = () => {
    window.print();
  };

  if (loading) return <Loader fullScreen={false} />;
  if (!invoice) return <div>Invoice not found</div>;

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      <div className="flex items-center justify-between print:hidden">
        <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:hover:text-slate-200">
          <ChevronLeft size={20} /> Back
        </button>
        <div className="flex gap-3">
          <button 
            onClick={handleDelete}
            className="flex items-center gap-2 px-4 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 dark:hover:bg-red-900/20"
          >
            <Trash2 size={18} /> Delete
          </button>
          <button 
            onClick={handlePrint}
            className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 shadow-md"
          >
            <Printer size={18} /> Print / Save PDF
          </button>
        </div>
      </div>

      <div className="flex justify-center">
        <InvoicePreview 
          company={company}
          invoice={invoice}
          items={invoice.items}
          subtotal={invoice.subtotal}
          discount={invoice.discount}
          tax={invoice.tax}
          total={invoice.total}
        />
      </div>
    </div>
  );
};

export default InvoiceDetails;

import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';

type ThemeMode = 'light' | 'dark' | 'system';

interface ThemeContextType {
  theme: ThemeMode;
  setTheme: (theme: ThemeMode) => void;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};

export const ThemeProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [theme, setTheme] = useState<ThemeMode>(() => {
    return (localStorage.getItem('theme') as ThemeMode) || 'system';
  });

  useEffect(() => {
    const root = document.documentElement;
    const apply = (t: ThemeMode) => {
      if (t === 'dark') {
        root.classList.add('dark');
      } else if (t === 'light') {
        root.classList.remove('dark');
      } else {
        if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
          root.classList.add('dark');
        } else {
          root.classList.remove('dark');
        }
      }
    };
    apply(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme((prev) => (prev === 'dark' ? 'light' : 'dark'));
  };

  return (
    <ThemeContext.Provider value={{ theme, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { translations, Language } from '../utils/translations';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: keyof typeof translations['en']) => string;
  isRTL: boolean;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>(() => {
    return (localStorage.getItem('language') as Language) || 'en';
  });

  const isRTL = language === 'ar';

  useEffect(() => {
    localStorage.setItem('language', language);
    document.documentElement.lang = language;
    document.documentElement.dir = isRTL ? 'rtl' : 'ltr';
  }, [language, isRTL]);

  const t = (key: keyof typeof translations['en']) => {
    return translations[language][key] || translations['en'][key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t, isRTL }}>
      {children}
    </LanguageContext.Provider>
  );
};

import React, { createContext, useContext, useEffect, useState } from 'react';
import { BrowserRouter, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { onAuthStateChanged, User } from 'firebase/auth';
import { auth } from './firebase';
import { getCompanyByOwner } from './services/database';
import { Company, UserContextType } from './types';
import { ToastProvider } from './context/ToastContext';
import { Loader } from './components/Loader';
import { ThemeProvider } from './context/ThemeContext';
import { LanguageProvider } from './context/LanguageContext';

// Pages
import Landing from './pages/Landing';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import CompanySetup from './pages/CompanySetup';
import InvoiceList from './pages/InvoiceList';
import CreateInvoice from './pages/CreateInvoice';
import InvoiceDetails from './pages/InvoiceDetails';
import CustomerList from './pages/CustomerList';
import Settings from './pages/Settings';

// Layout
import SidebarLayout from './components/SidebarLayout';

const UserContext = createContext<UserContextType>({
  user: null,
  company: null,
  loading: true,
  refreshCompany: async () => {},
});

export const useUser = () => useContext(UserContext);

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [company, setCompany] = useState<Company | null>(null);
  const [loading, setLoading] = useState(true);

  const refreshCompany = async (uid?: string) => {
    const userId = uid || user?.uid;
    if (userId) {
      const companyData = await getCompanyByOwner(userId);
      setCompany(companyData);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        await refreshCompany(currentUser.uid);
      } else {
        setCompany(null);
      }
      setLoading(false);
    });
    return () => unsubscribe();
  }, [user?.uid]);

  if (loading) {
    return <Loader fullScreen={true} />;
  }

  return (
    <ThemeProvider>
      <LanguageProvider>
        <ToastProvider>
          <UserContext.Provider value={{ user, company, loading, refreshCompany }}>
            <BrowserRouter>
              <Routes>
                <Route path="/" element={<RootRoute />} />
                <Route path="/login" element={!user ? <Login /> : <Navigate to="/dashboard" replace />} />

                <Route element={<ProtectedRoute />}>
                  {/* Dashboard and Main App Routes - No longer requires company check for access */}
                  <Route element={<SidebarLayout />}>
                    <Route path="/dashboard" element={<Dashboard />} />
                    <Route path="/invoices" element={<InvoiceList />} />
                    <Route path="/invoices/new" element={<CreateInvoice />} />
                    <Route path="/invoices/:customerId/:invoiceId" element={<InvoiceDetails />} />
                    <Route path="/customers" element={<CustomerList />} />
                    <Route path="/settings" element={<Settings />} />
                  </Route>

                  {/* Setup Route */}
                  <Route path="/setup" element={<CompanySetup />} />
                </Route>

                <Route path="*" element={<Navigate to="/" replace />} />
              </Routes>
            </BrowserRouter>
          </UserContext.Provider>
        </ToastProvider>
      </LanguageProvider>
    </ThemeProvider>
  );
};

const RootRoute = () => {
  const { user } = useUser();
  // Redirect strictly based on login status, ignoring company existence
  if (user) {
    return <Navigate to="/dashboard" replace />;
  }
  return <Landing />;
};

const ProtectedRoute = () => {
  const { user } = useUser();
  return user ? <Outlet /> : <Navigate to="/login" replace />;
};

export default App;

