import React, { useState } from 'react';
import { auth, googleProvider } from '../firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signInWithPopup
} from 'firebase/auth';
import { Mail, Lock, Chrome, AlertCircle } from 'lucide-react';
import { useToast } from '../context/ToastContext';
import { Logo } from '../components/Logo';
import { useLanguage } from '../context/LanguageContext';

const Login: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [loading, setLoading] = useState(false);
  const { error, success } = useToast();
  const { t, isRTL } = useLanguage();

  const handleEmailAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (isRegistering) {
        await createUserWithEmailAndPassword(auth, email, password);
        success('Account created successfully!');
      } else {
        await signInWithEmailAndPassword(auth, email, password);
        success(t('welcomeBack'));
      }
    } catch (err: any) {
      error(err.message || 'Authentication failed');
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    try {
      await signInWithPopup(auth, googleProvider);
      success('Signed in with Google');
    } catch (err: any) {
      error(err.message || 'Google sign in failed');
    }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-900 flex flex-col items-center justify-center p-4 ${isRTL ? 'text-right' : 'text-left'}`}>
      <div className="w-full max-w-md">
        <div className="text-center mb-10">
          <div className="h-16 w-16 bg-primary rounded-2xl flex items-center justify-center shadow-lg shadow-primary/20 mx-auto mb-6">
            <Logo className="text-white" size={32} />
          </div>
          <h1 className="text-3xl font-extrabold text-slate-900 dark:text-white tracking-tight">{t('welcomeBack')}</h1>
          <p className="text-slate-500 dark:text-slate-400 mt-2">{t('manageBusiness')}</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700">
          <form onSubmit={handleEmailAuth} className="space-y-5">
            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">{t('emailLabel')}</label>
              <div className="relative">
                <Mail className={`absolute ${isRTL ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-primary`} size={20} />
                <input
                  type="email"
                  required
                  placeholder={t('enterEmail')}
                  className={`input-primary ${isRTL ? 'pr-12' : 'pl-12'}`}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">{t('passwordLabel')}</label>
              <div className="relative">
                <Lock className={`absolute ${isRTL ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-primary`} size={20} />
                <input
                  type="password"
                  required
                  placeholder={t('enterPassword')}
                  className={`input-primary ${isRTL ? 'pr-12' : 'pl-12'}`}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className={`w-full bg-primary text-white py-4 rounded-xl font-bold shadow-lg shadow-primary/30 hover:bg-primary/90 transition-all flex items-center justify-center gap-2 ${isRTL ? 'flex-row-reverse' : ''}`}
            >
              {loading ? (
                <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              ) : (
                <>{isRegistering ? t('createAccount') : t('signIn')}</>
              )}
            </button>
          </form>

          <div className="mt-8 relative text-center">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-slate-200 dark:border-slate-700"></div>
            </div>
            <span className="relative bg-white dark:bg-slate-800 px-4 text-sm text-slate-400 font-medium">OR</span>
          </div>

          <button
            onClick={handleGoogleSignIn}
            className={`w-full mt-8 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-700 dark:text-white py-4 rounded-xl font-bold hover:bg-slate-50 dark:hover:bg-slate-600 transition-all flex items-center justify-center gap-3 ${isRTL ? 'flex-row-reverse' : ''}`}
          >
            <Chrome size={20} className="text-primary" />
            {t('continueGoogle')}
          </button>

          <p className="mt-8 text-center text-slate-600 dark:text-slate-400 font-medium">
            {isRegistering ? t('hasAccount') : t('noAccount')}{' '}
            <button
              onClick={() => setIsRegistering(!isRegistering)}
              className="text-primary font-bold hover:underline"
            >
              {isRegistering ? t('signIn') : t('createAccount')}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { useUser } from '../App';
import { createCompany, updateCompany } from '../services/database';
import { uploadToImgBB } from '../services/imgbb';
import { useNavigate } from 'react-router-dom';
import { Building2, Mail, Phone, MapPin, Upload, ChevronRight, PlusCircle, ArrowLeft } from 'lucide-react';
import { useToast } from '../context/ToastContext';
import { Logo } from '../components/Logo';
import { useLanguage } from '../context/LanguageContext';

const CompanySetup: React.FC = () => {
  const { user, company, refreshCompany } = useUser();
  const navigate = useNavigate();
  const { success, error } = useToast();
  const { t, isRTL } = useLanguage();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    address: '',
  });
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);

  // Pre-fill data if company exists (Edit Mode)
  useEffect(() => {
    if (company) {
      setFormData({
        name: company.name,
        email: company.email,
        phone: company.phone,
        address: company.address,
      });
      if (company.photo) {
        setLogoPreview(company.photo);
      }
    }
  }, [company]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setLogoFile(file);
      setLogoPreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    setLoading(true);

    try {
      let photo = company?.photo || '';
      if (logoFile) {
        photo = await uploadToImgBB(logoFile);
      }

      if (company?.id) {
        // Update existing
        await updateCompany(user.uid, company.id, {
          ...formData,
          photo,
        });
        success('Company profile updated!');
        navigate('/settings');
      } else {
        // Create new
        await createCompany({
          ...formData,
          photo,
          ownerUid: user.uid,
          currency: '$',
          paymentMethods: ['Cash', 'Card', 'Bank Transfer'],
          templateId: 'standard'
        });
        success('Welcome! Company profile setup complete.');
        navigate('/dashboard');
      }

      await refreshCompany();
    } catch (err) {
      console.error(err);
      error('Failed to save company profile.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-900 flex items-center justify-center p-6 ${isRTL ? 'text-right' : 'text-left'}`}>
      <div className={`max-w-2xl w-full bg-white dark:bg-slate-800 rounded-3xl shadow-xl overflow-hidden flex flex-col md:flex-row relative ${isRTL ? 'md:flex-row-reverse' : ''}`}>
        {company && (
          <button 
            onClick={() => navigate('/settings')}
            className={`absolute top-4 ${isRTL ? 'right-4' : 'left-4'} z-10 p-2 bg-white/20 hover:bg-white/40 backdrop-blur-sm rounded-full text-white transition-colors`}
          >
            <ArrowLeft size={20} className={isRTL ? 'rotate-180' : ''} />
          </button>
        )}

        <div className="md:w-1/3 bg-primary p-8 text-white flex flex-col justify-center">
          <Logo className="text-white mb-4" size={48} />
          <h1 className="text-2xl font-bold mb-2">{company ? t('editProfile') : t('companySetup')}</h1>
          <p className="text-primary-foreground/80 text-sm leading-relaxed">
            {company ? t('setupDescEdit') : t('setupDescNew')}
          </p>
        </div>

        <div className="md:w-2/3 p-8 lg:p-12">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="flex justify-center mb-8">
              <label className="relative cursor-pointer group">
                <div className="w-24 h-24 rounded-2xl bg-slate-100 dark:bg-slate-700 border-2 border-dashed border-primary/30 flex items-center justify-center overflow-hidden transition-all group-hover:border-primary">
                  {logoPreview ? (
                    <img src={logoPreview} alt="Logo Preview" className="w-full h-full object-cover" />
                  ) : (
                    <div className="text-center text-slate-400">
                      <Upload size={24} className="mx-auto mb-1" />
                      <span className="text-[10px] font-bold uppercase">{t('logo')}</span>
                    </div>
                  )}
                </div>
                <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
                <div className={`absolute -bottom-2 ${isRTL ? '-left-2' : '-right-2'} bg-primary text-white p-1.5 rounded-lg shadow-lg`}>
                  <PlusCircle size={14} />
                </div>
              </label>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">{t('companyName')}</label>
                <div className="relative">
                  <Building2 size={16} className={`absolute ${isRTL ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-primary`} />
                  <input
                    type="text"
                    required
                    placeholder="E.g. Acme Corp"
                    className={`input-primary ${isRTL ? 'pr-11' : 'pl-11'}`}
                    value={formData.name}
                    onChange={(e) => setFormData({...formData, name: e.target.value})}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">{t('emailLabel')}</label>
                  <div className="relative">
                    <Mail size={16} className={`absolute ${isRTL ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-primary`} />
                    <input
                      type="email"
                      required
                      placeholder="billing@acme.com"
                      className={`input-primary ${isRTL ? 'pr-11' : 'pl-11'} text-sm`}
                      value={formData.email}
                      onChange={(e) => setFormData({...formData, email: e.target.value})}
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">{t('phone')}</label>
                  <div className="relative">
                    <Phone size={16} className={`absolute ${isRTL ? 'right-4' : 'left-4'} top-1/2 -translate-y-1/2 text-primary`} />
                    <input
                      type="tel"
                      required
                      placeholder="+1 234 567"
                      className={`input-primary ${isRTL ? 'pr-11' : 'pl-11'} text-sm`}
                      value={formData.phone}
                      onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    />
